; =============================================================================
; Final Fantasy Legend II (U) [!].gb - Square sound driver (FFL2/FFA generation)
; Bank $0E $4000-$7FE8.  Generated by tools/gen_g2.py; label and RAM names from FFL2_audio.s.
; Rebuilds byte-exact with RGBDS 0.9.x:
;   rgbasm -Wall -o snd.o <this file> ; rgblink -o snd.gb snd.o ; python tools/cmp_bank.py <this file> <rom> snd.gb
; =============================================================================

DEF rNR10    EQU $FF10
DEF rNR11    EQU $FF11
DEF rNR12    EQU $FF12
DEF rNR13    EQU $FF13
DEF rNR14    EQU $FF14
DEF rNR21    EQU $FF16
DEF rNR22    EQU $FF17
DEF rNR23    EQU $FF18
DEF rNR24    EQU $FF19
DEF rNR30    EQU $FF1A
DEF rNR31    EQU $FF1B
DEF rNR32    EQU $FF1C
DEF rNR33    EQU $FF1D
DEF rNR34    EQU $FF1E
