DEF rNR42    EQU $FF21
DEF rNR43    EQU $FF22
DEF rNR44    EQU $FF23
DEF rNR50    EQU $FF24
DEF rNR51    EQU $FF25
DEF rNR52    EQU $FF26

DEF w_music_time_divider                           EQU $CB00
DEF w_music_tempo                                  EQU $CB01
DEF w_mctrl1_music_timer                           EQU $CB03
DEF w_mctrl1_stream_ptr                            EQU $CB04
DEF w_mctrl1_pitch_fx_timer                        EQU $CB06
DEF w_mctrl1_pitch_fx_ptr_start                    EQU $CB07
DEF w_mctrl1_pitch_fx_ptr_current                  EQU $CB09
DEF w_mctrl1_octave                                EQU $CB0B
DEF w_mctrl1_wave_duty                             EQU $CB0C
DEF w_mctrl1_freq_low                              EQU $CB0D
DEF w_mctrl1_freq_high                             EQU $CB0E
DEF w_mctrl1_loop_counter                          EQU $CB0F
DEF w_mctrl1_last_note                             EQU $CB11
DEF w_mctrl1_enable                                EQU $CB13
DEF w_mctrl1_volume_fx_timer                       EQU $CB14
DEF w_mctrl1_volume_fx_ptr_start                   EQU $CB15
DEF w_mctrl1_volume_fx_ptr_current                 EQU $CB17
DEF w_mctrl1_alt_loop_counter                      EQU $CB19
DEF w_mctrl2_sound_timer                           EQU $CB1A
DEF w_mctrl2_music_timer                           EQU $CB1B
DEF w_mctrl2_stream_ptr                            EQU $CB1C
DEF w_mctrl2_pitch_fx_timer                        EQU $CB1E
DEF w_mctrl2_pitch_fx_ptr_start                    EQU $CB1F
DEF w_mctrl2_pitch_fx_ptr_current                  EQU $CB21
DEF w_mctrl2_octave                                EQU $CB23
DEF w_mctrl2_wave_duty                             EQU $CB24
DEF w_mctrl2_freq_low                              EQU $CB25
DEF w_mctrl2_freq_high                             EQU $CB26
DEF w_mctrl2_loop_counter                          EQU $CB27
DEF w_mctrl2_last_note                             EQU $CB29
DEF w_mctrl2_pan                                   EQU $CB2A
DEF w_mctrl2_enable                                EQU $CB2B
DEF w_mctrl2_volume_fx_timer                       EQU $CB2C
DEF w_mctrl2_volume_fx_ptr_start                   EQU $CB2D
DEF w_mctrl2_volume_fx_ptr_current                 EQU $CB2F
DEF w_mctrl2_alt_loop_counter                      EQU $CB31
DEF w_mctrl3_music_timer                           EQU $CB33
DEF w_mctrl3_stream_ptr                            EQU $CB34
DEF w_mctrl3_pitch_fx_timer                        EQU $CB36
DEF w_mctrl3_pitch_fx_ptr_start                    EQU $CB37
DEF w_mctrl3_pitch_fx_ptr_current                  EQU $CB39
DEF w_mctrl3_octave                                EQU $CB3B
DEF w_mctrl3_freq_low                              EQU $CB3D
DEF w_mctrl3_freq_high                             EQU $CB3E
DEF w_mctrl3_loop_counter                          EQU $CB3F
DEF w_mctrl3_wave_volume                           EQU $CB40
DEF w_mctrl3_last_note                             EQU $CB41
DEF w_mctrl3_enable                                EQU $CB43
DEF w_mctrl3_alt_loop_counter                      EQU $CB49
DEF w_mctrl4_sound_timer                           EQU $CB4A
DEF w_mctrl4_enable                                EQU $CB5B
DEF w_sfx_tone_stream_ptr                          EQU $CBC4
DEF w_sfx_noise_stream_ptr                         EQU $CBC6
DEF h_bg_music                                     EQU $FFB0
DEF h_fg_music                                     EQU $FFB1
DEF h_sfx                                          EQU $FFB2
DEF h_current_bg_music                             EQU $FFB3
DEF h_music_effect_channel                         EQU $FFB4
DEF h_note_length_1                                EQU $FFB5
DEF h_note_length_2                                EQU $FFB6
DEF h_note_length_3                                EQU $FFB7
DEF h_fg_music_flag                                EQU $FFB9
DEF h_wave_sample                                  EQU $FFBA
DEF h_sfx_tone_loop_counter                        EQU $FFBC
DEF h_sfx_noise_loop_counter                       EQU $FFBD

; ---------------------------------------------------------------- music macros
; note byte = length index << 4 | pitch;  pitch 0-B = C..B, C/D = C/C# one octave up, E = tie, F = rest
DEF C_   EQU 0
DEF Cs_  EQU 1
DEF D_   EQU 2
DEF Ds_  EQU 3
DEF E_   EQU 4
DEF F_   EQU 5
DEF Fs_  EQU 6
DEF G_   EQU 7
DEF Gs_  EQU 8
DEF A_   EQU 9
DEF As_  EQU 10
DEF B_   EQU 11
DEF C2_  EQU 12
DEF Cs2_ EQU 13
DEF L96  EQU 0
DEF L72  EQU 1
DEF L48  EQU 2
DEF L32  EQU 3
DEF L36  EQU 4
DEF L24  EQU 5
DEF L16  EQU 6
DEF L18  EQU 7
DEF L12  EQU 8
DEF L8   EQU 9
DEF L6   EQU 10
DEF L4   EQU 11
DEF L3   EQU 12
MACRO note      ; pitch, ticks
    db L\2 << 4 | (\1)
ENDM
MACRO tie       ; ticks
    db L\1 << 4 | $E
ENDM
MACRO rest      ; ticks
    db L\1 << 4 | $F
ENDM
MACRO octave    ; 0-7
    db $D0 | (\1)
ENDM
MACRO oct_up    ; 1-4
    db $D8 | ((\1) - 1)
ENDM
MACRO oct_down  ; 1-4
    db $DC | ((\1) - 1)
ENDM
MACRO vol_fx    ; CH1/CH2
    db $E0
    dw \1
ENDM
MACRO volume    ; CH3: NR32
    db $E0, \1
ENDM
MACRO jump
    db $E1
    dw \1
ENDM
MACRO loop_a    ; --A != 0 -> jump
    db $E2
    dw \1
ENDM
MACRO set_a
    db $E3, \1
ENDM
MACRO pitch_fx
    db $E4
    dw \1
ENDM
MACRO duty      ; CH1/CH2
    db $E5, \1
ENDM
MACRO pan       ; 0 off, 1 right, 2 left, 3 both
    db $E6, \1
ENDM
MACRO tempo     ; CH2
    db $E7, \1
ENDM
MACRO wave      ; CH3
    db $E8
    dw \1
ENDM
MACRO loop_b
    db $E9
    dw \1
ENDM
MACRO set_b
    db $EA, \1
ENDM
MACRO if_a      ; A == n -> jump
    db $EB, \1
    dw \2
ENDM
MACRO doubletime ; FFA CH2 only: sets a flag the tick code never really tests
    db $EC, \1
ENDM
MACRO end_track
    db $FF
ENDM
MACRO fx        ; frames/3, value (NRx2, or signed period offset)
    db \1, (\2) & $FF
ENDM
MACRO fx_jump
    db 0
    dw \1
ENDM
MACRO sfx_tone  ; frames, NR10..NR14
    db \1, \2, \3, \4, \5, \6
ENDM
MACRO sfx_noise ; frames, NR42, NR43
    db \1, \2, \3
ENDM
MACRO sfx_count
    db $F0 | (\1)
ENDM
MACRO sfx_loop
    db $EF
    dw \1
ENDM
MACRO sfx_end
    db 0
ENDM

SECTION "Sound", ROMX[$4000], BANK[$0E]

xe_update_audio:
    jr update_audio
    db $00

xe_reset_audio:
    jr reset_audio
    db $00

update_audio:
    push af
    push bc
    push de
    push hl
    ldh a, [h_fg_music]
    or a
    jr z, update_audio.l401E
    ldh a, [h_fg_music_flag]
    or a
    jr z, update_audio.l4019
    call update_foreground_music
    jr L000
.l4019:
    call play_foreground_music
    jr L000
.l401E:
    ldh a, [h_fg_music_flag]
    or a
    jr z, update_audio.l4028
    call stop_foreground_music
    jr L000
.l4028:
    ld a, [w_mctrl2_sound_timer]
    or a
    jr nz, update_audio.l4037
    ldh a, [h_current_bg_music]
    ld b, a
    ldh a, [h_bg_music]
    cp b
    call nz, play_background_music
.l4037:
    ldh a, [h_sfx]
    or a
    call nz, play_sound

L000:
    call update_music
    call update_sound
    pop hl
    pop de
    pop bc
    pop af
    ret

reset_audio:
    ld a, $FF
    ldh [rNR52], a
    call reset_music_control
    ld a, $FF
    ld [w_mctrl1_enable], a
    ld [w_mctrl2_enable], a
    ld [w_mctrl3_enable], a
    ld [w_mctrl4_enable], a
    ld a, $10
    ldh [rNR12], a
    ldh [rNR22], a
    ldh [rNR32], a
    ldh [rNR42], a
    call silence_audio
    xor a
    ld [w_mctrl2_sound_timer], a
    ld a, $77
    ldh [rNR50], a
    ld a, $FF
    ldh [rNR51], a
    ld hl, h_bg_music
    ld c, $10
    xor a
.l407C:
    ld [hli], a
    dec c
    jr nz, reset_audio.l407C
    ret

reset_music_control:
    ld hl, w_music_time_divider
    ld a, $FF
    ld [hli], a
    ld a, $3C
    ld [hli], a
    ld b, $03
.l408C:
    ld de, audio_init_data
    ld c, $18
.l4091:
    ld a, [de]
    ld [hli], a
    inc e
    dec c
    jr nz, reset_music_control.l4091
    dec b
    jr nz, reset_music_control.l408C
    ret

play_background_music:
    ldh [h_current_bg_music], a
    or a
    jr nz, play_music
    call reset_audio
    ret

play_music:
    push af
    call reset_music_control
    pop af
    dec a
    ld e, a
    add a, a
    add a, e
    add a, a
    ld hl, SongTable
    ld e, a
    ld d, $00
    add hl, de
    ld a, [hli]
    ld [w_mctrl1_stream_ptr], a
    ld a, [hli]
    ld [w_mctrl1_stream_ptr+1], a
    ld a, [hli]
    ld [w_mctrl2_stream_ptr], a
    ld a, [hli]
    ld [w_mctrl2_stream_ptr+1], a
    ld a, [hli]
    ld [w_mctrl3_stream_ptr], a
    ld a, [hli]
    ld [w_mctrl3_stream_ptr+1], a
    ret

silence_audio:
    xor a
    ldh [rNR10], a
    ld a, $FF
    ldh [rNR13], a
    ldh [rNR23], a
    ldh [rNR31], a
    ldh [rNR33], a
    ld a, $07
    ldh [rNR14], a
    ldh [rNR24], a
    ldh [rNR34], a
    xor a
    ldh [rNR42], a
    ld a, $80
    ldh [rNR44], a
    ret

play_foreground_music:
    call silence_audio
    xor a
    ld [w_mctrl2_sound_timer], a
    ld [w_mctrl4_sound_timer], a
    ld c, $62
    ld hl, w_music_time_divider
    ld de, $CB62
.l40FD:
    ld a, [hli]
    ld [de], a
    inc e
    dec c
    jr nz, play_foreground_music.l40FD
    ldh a, [h_fg_music]
    call play_music
    ld a, $01
    ldh [h_fg_music_flag], a
    ret

update_foreground_music:
    ld a, [w_mctrl1_enable]
    ld e, a
    ld a, [w_mctrl2_enable]
    ld d, a
    ld a, [w_mctrl3_enable]
    and d
    and e
    cp $FF
    ret nz

stop_foreground_music:
    call silence_audio
    ld c, $62
    ld hl, w_music_time_divider
    ld de, $CB62
.l4128:
    ld a, [de]
    ld [hli], a
    inc e
    dec c
    jr nz, stop_foreground_music.l4128
    xor a
    ldh [h_fg_music], a
    ldh [h_fg_music_flag], a
    ld a, [w_mctrl1_wave_duty]
    ldh [rNR21], a
    ld a, [w_mctrl1_loop_counter+1]
    ldh [rNR22], a
    ld a, $87
    ldh [rNR24], a
    ldh a, [h_wave_sample]
    ld l, a
    ldh a, [h_wave_sample+1]
    ld h, a
    call load_wave_sample

stop_sound_tone_channel:
    xor a
    ldh [rNR10], a
    ld a, [w_mctrl2_wave_duty]
    ldh [rNR11], a
    ld a, [w_mctrl2_loop_counter+1]
    ldh [rNR12], a
    ld a, $FF
    ldh [rNR13], a
    ld a, $87
    ldh [rNR14], a
    ld a, [w_mctrl2_pan]
    ld e, a
    ldh a, [rNR51]
    and $EE
    or e
    ldh [rNR51], a
    ret

stop_sound_noise_channel:
    xor a
    ldh [rNR42], a
    ldh [rNR43], a
    ld a, $80
    ldh [rNR44], a
    ret

audio_init_data:
    db $00, $01 ; +0 sfx timer, +1 note timer
    dw $0000       ; +2 stream pointer
    db $14        ; +4 pitch fx timer
    dw default_pitch_fx, default_pitch_fx
    db $60, $00, $00, $00, $00, $10, $0F, $00, $00 ; +9..+$11 (+$11 = ended flag)
    db $01        ; +$12 volume fx timer
    dw default_volume_fx, default_volume_fx
    ; (23 bytes: the $18-byte copy also takes DefaultPitchFx's first byte ($0A) as loop counter B)

default_pitch_fx:
    fx $0A, $00
.l418E:
    fx $02, $01
    fx $02, $00
    fx_jump default_pitch_fx.l418E

default_volume_fx:
    fx $FF, $F0
    fx_jump default_volume_fx

note_freq_table:
    ; period | $8000 (trigger); index = octave*24 + pitch*2
    dw $802C, $809D, $8107, $816B, $81C9, $8223, $8277, $82C7, $8312, $8358, $839B, $83DA
    dw $8416, $844E, $8483, $84B5, $84E5, $8511, $853B, $8563, $8589, $85AC, $85CE, $85ED
    dw $860B, $8627, $8642, $865B, $8672, $8689, $869E, $86B2, $86C4, $86D6, $86E7, $86F7
    dw $8706, $8714, $8721, $872D, $8739, $8744, $874F, $8759, $8762, $876B, $8773, $877B
    dw $8783, $878A, $8790, $8797, $879D, $87A2, $87A7, $87AC, $87B1, $87B6, $87BA, $87BE
    dw $87C1, $87C5, $87C8, $87CB, $87CE, $87D1, $87D4, $87D6, $87D9, $87DB, $87DD, $87DF
    dw $87E1, $87E2, $87E4, $87E6, $87E7, $87E9, $87EA, $87EB, $87EC, $87ED, $87EE, $87EF
    dw $87F0

note_length_table:
    db $60, $48, $30, $20, $24, $18, $10, $12, $0C, $08, $06, $04, $03

update_music:
    ld a, [w_music_time_divider]
    ld b, a
    ld a, [w_music_tempo]
    add a, b
    ld [w_music_time_divider], a
    jr nc, update_music.l4264
    call update_music_streams
    call update_music_streams
.l4264:
    ldh a, [h_music_effect_channel]
    inc a
    cp $03
    jr nz, update_music.l426C
    xor a
.l426C:
    ldh [h_music_effect_channel], a
    or a
    call z, update_music_channel_0_effects
    ldh a, [h_music_effect_channel]
    cp $01
    call z, update_music_channel_1_effects
    ldh a, [h_music_effect_channel]
    cp $02
    call z, update_music_channel_2_effects
    ret

update_music_streams:
    ld a, [w_mctrl1_enable]
    cp $FF
    jp z, _update_music_streams_channel_1
    ld a, [w_mctrl1_music_timer]
    dec a
    ld [w_mctrl1_music_timer], a
    ldh [h_note_length_1], a
    jp nz, _update_music_streams_channel_1

_next_byte_channel_0:
    call music_channel_0_stream_read_1
    ld e, a
    cp $D0
    jr nc, _next_byte_channel_0.l4307
    and $F0
    swap a
    ld c, a
    ld hl, note_length_table
    ld b, $00
    add hl, bc
    ld a, [hl]
    ld [w_mctrl1_music_timer], a
    ld a, e
    and $0F
    ld [w_mctrl1_last_note], a
    cp $0E
    jp z, _update_music_streams_channel_1
    cp $0F
    jr nz, _next_byte_channel_0.l42C6
    ld a, $FF
    ldh [rNR23], a
    ld a, $07
    ldh [rNR24], a
    jp _update_music_streams_channel_1
.l42C6:
    add a, a
    ld e, a
    ld a, [w_mctrl1_octave]
    add a, e
    ld e, a
    ld d, $00
    ld hl, note_freq_table
    add hl, de
    push hl
    ld a, [w_mctrl1_volume_fx_ptr_start]
    ld l, a
    ld a, [w_mctrl1_volume_fx_ptr_start+1]
    ld h, a
    ld a, [hli]
    ld [w_mctrl1_volume_fx_timer], a
    ld a, [hli]
    ldh [rNR22], a
    ld a, l
    ld a, [w_mctrl1_volume_fx_ptr_current]
    ld a, h
    ld a, [w_mctrl1_volume_fx_ptr_current+1]
    pop hl
    ld a, [hli]
    ldh [rNR23], a
    ld [w_mctrl1_freq_low], a
    ld a, [hl]
    ldh [rNR24], a
    ld [w_mctrl1_freq_high], a
    ld hl, w_mctrl1_pitch_fx_timer
    call restart_music_channel_effect
    ld hl, w_mctrl1_volume_fx_timer
    call restart_music_channel_effect
    jp _update_music_streams_channel_1
.l4307:
    cp $FF
    jr nz, _next_byte_channel_0.l4317
    ld [w_mctrl1_enable], a
    ldh [rNR23], a
    ld a, $07
    ldh [rNR24], a
    jp _update_music_streams_channel_1
.l4317:
    cp $E0
    jr nc, _next_byte_channel_0.l4341
    bit 3, a
    jr nz, _next_byte_channel_0.l432D
    and $07
    add a, a
    add a, a
    add a, a
    ld e, a
    add a, a
    add a, e
    ld [w_mctrl1_octave], a
    jp _next_byte_channel_0
.l432D:
    and $07
    ld e, a
    ld d, $00
    ld hl, octave_table
    add hl, de
    ld e, [hl]
    ld a, [w_mctrl1_octave]
    add a, e
    ld [w_mctrl1_octave], a
    jp _next_byte_channel_0
.l4341:
    and $0F
    add a, a
    ld hl, _jt_ch0_command
    ld e, a
    ld d, $00
    add hl, de
    call dispatch_music_channel_0_command
    jp _next_byte_channel_0

dispatch_music_channel_0_command:
    ld a, [hli]
    ld e, a
    ld a, [hl]
    ld h, a
    ld l, e
    jp hl

music_command_null_handler:
    ret

_jt_ch0_command:
    dw music_channel_0_volume_effect            ; $E0
    dw music_channel_0_jump                     ; $E1
    dw music_channel_0_loop_counter_jump        ; $E2
    dw music_channel_0_loop_counter             ; $E3
    dw music_channel_0_pitch_effect             ; $E4
    dw music_channel_0_wave_duty                ; $E5
    dw music_channel_0_pan                      ; $E6
    dw music_set_tempo                          ; $E7
    dw music_command_null_handler               ; $E8  (null)
    dw music_channel_0_loop_counter_2_jump      ; $E9
    dw music_channel_0_loop_counter_2           ; $EA
    dw music_channel_0_compare_jump             ; $EB

music_channel_0_volume_effect:
    ld hl, w_mctrl1_stream_ptr
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    inc de
    ld [w_mctrl1_volume_fx_ptr_start+1], a
    ld [w_mctrl1_volume_fx_ptr_current+1], a
    ld a, c
    ld [w_mctrl1_volume_fx_ptr_start], a
    ld [w_mctrl1_volume_fx_ptr_current], a
    ld a, e
    ld [w_mctrl1_stream_ptr], a
    ld a, d
    ld [w_mctrl1_stream_ptr+1], a
    ret

music_channel_0_jump:
    ld hl, w_mctrl1_stream_ptr
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    inc de
    ld [w_mctrl1_stream_ptr], a
    ld a, [de]
    ld [w_mctrl1_stream_ptr+1], a
    ret

music_channel_0_loop_counter_jump:
    ld hl, w_mctrl1_stream_ptr
    call music_stream_read_2_helper
    ld b, a
    ld a, [w_mctrl1_loop_counter]
    dec a
    ld [w_mctrl1_loop_counter], a
    jr music_stream_conditional_jump

music_channel_1_loop_counter_jump:
    ld hl, w_mctrl2_stream_ptr
    call music_stream_read_2_helper
    ld b, a
    ld a, [w_mctrl2_loop_counter]
    dec a
    ld [w_mctrl2_loop_counter], a
    jr music_stream_conditional_jump

music_channel_2_loop_counter_jump:
    ld hl, w_mctrl3_stream_ptr
    call music_stream_read_2_helper
    ld b, a
    ld a, [w_mctrl3_loop_counter]
    dec a
    ld [w_mctrl3_loop_counter], a
    jr music_stream_conditional_jump

music_channel_0_loop_counter_2_jump:
    ld hl, w_mctrl1_stream_ptr
    call music_stream_read_2_helper
    ld b, a
    ld a, [w_mctrl1_alt_loop_counter]
    dec a
    ld [w_mctrl1_alt_loop_counter], a
    jr music_stream_conditional_jump

music_channel_1_loop_counter_2_jump:
    ld hl, w_mctrl2_stream_ptr
    call music_stream_read_2_helper
    ld b, a
